begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_table('public','generation_runs','Las generaciones tienen un registro independiente de la escritura Gmail');
select has_column('public','draft_generations','generation_run_id','Los borradores referencian su generación');
select has_index('public','draft_generations','draft_generations_generation_run_owner_idx','La referencia de generación tiene índice de propietario');
select has_index('public','generation_content_authorizations','generation_content_authorizations_account_owner_idx','La autorización tiene índice de cuenta y propietario');
select ok((select relrowsecurity from pg_class where oid='public.generation_runs'::regclass),'RLS activo en metadatos');
select ok((select relrowsecurity from pg_class where oid='public.generation_temporary_content'::regclass),'RLS activo en contenido temporal');
select ok(not has_table_privilege('authenticated','public.generation_temporary_content','SELECT'),'El navegador no puede leer textos');
select ok(not has_table_privilege('anon','public.generation_runs','SELECT'),'No hay acceso anónimo a metadatos');
select ok(not has_table_privilege('authenticated','public.generation_runs','INSERT'),'El navegador no puede inventar generaciones');
select ok(not has_table_privilege('service_role','public.generation_runs','UPDATE'),'Los metadatos no se reescriben');
select ok(not has_table_privilege('service_role','public.generation_runs','TRUNCATE'),'El worker no puede truncar metadatos');
select ok(not has_table_privilege('service_role','public.generation_runs','TRIGGER'),'El worker no puede modificar triggers de metadatos');
select ok(has_column_privilege('service_role','public.generation_runs','configuration','UPDATE'),'La copia de identidad permite su supresión explícita');
select ok(not has_function_privilege('authenticated','public.guard_generation_identity_redaction()','EXECUTE'),'La función de supresión de identidad no es pública');
select ok(not has_function_privilege('authenticated','public.set_generation_retention(uuid,uuid,boolean,integer,text)','EXECUTE'),'La autorización exige acceso de usuario validado en servidor');
select ok(not has_function_privilege('anon','public.read_generation_content(uuid,uuid)','EXECUTE'),'No se expone el contenido mediante RPC pública');
select ok(not has_function_privilege('authenticated','public.purge_generation_content()','EXECUTE'),'La purga no es pública');
select ok(has_function_privilege('service_role','public.purge_generation_content()','EXECUTE'),'El worker puede ejecutar la purga');
select is((select count(*) from cron.job where jobname='mail056-purge-generation-content' and active and schedule='*/5 * * * *'),1::bigint,'Purga automática activa cada cinco minutos');
select ok((select command='select public.purge_generation_content()' from cron.job where jobname='mail056-purge-generation-content'),'La tarea programada ejecuta la purga');
select * from finish();
rollback;
